program='''import copy

def components(cells, diagonal=False):
    unseen = set(cells); result = []
    steps = [(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1)
             if (dr or dc) and (diagonal or dr == 0 or dc == 0)]
    while unseen:
        seed = unseen.pop(); comp = {seed}; stack = [seed]
        while stack:
            r,c = stack.pop()
            for dr,dc in steps:
                q = (r+dr,c+dc)
                if q in unseen:
                    unseen.remove(q); comp.add(q); stack.append(q)
        result.append(comp)
    return result

def transform(grid):
    out = copy.deepcopy(grid); bg = grid[3][19]
    marks = {(r,c) for r in range(5) for c in range(5)
             if grid[r+1][c+1] != bg}
    wall = max(components(marks, True), key=len)
