    def key(comp):
        return (sum(r+c for r,c in comp)/len(comp),
                sum(c for r,c in comp)/len(comp),
                -sum(r for r,c in comp)/len(comp))
    bcomp = min(comps, key=key)
    for r in range(5):
        for c in range(5):
            b = grid[r+1][c+7]; cc = grid[r+1][c+13]
            out[r+1][c+19] = ((b if b != bg else cc) if (r,c) in wall
